var a=158;var i=`158-quick-pickles-and-acid-based-condiments`;var s=`154`;var r={en:`Quick Pickles and Acid-Based Condiments`,ua:`Швидке маринування та кислі приправи`};var n={short:`Quick pickles use an acidic liquid to create tangy flavor and change the texture of vegetables within a short time. They are refrigerator foods, not automatically shelf-stable preserves.`,sections:[{title:`Core idea`,text:`Sliced cucumber, onion or radish can be submerged in a mixture of vinegar, water, salt and sometimes sugar. Acidity and diffusion change perceived flavor; thin slices respond faster than thick pieces.`},{title:`Science`,text:`Organic acids alter flavor and some plant-tissue properties. Salt and sugar affect osmotic movement of water. Acid penetration is not instant, and a pleasant sour taste does not prove that a jar has a validated preservation pH.`},{title:`How to apply`,text:`Use clean produce, a food-safe container and a tested refrigerator-pickle formula. Keep refrigerated, date the preparation and use within the recipe's guidance. For shelf-stable canning, follow a separate tested canning procedure.`},{title:`Practical experiment`,text:`Compare thin and thick red-onion slices after 15 and 60 minutes in the same cold pickling liquid. Record color, crunch and sharpness without treating the product as shelf-stable.`},{title:`Common mistakes`,text:`Reducing vinegar arbitrarily or assuming that any acidic liquid prevents botulism is unsafe. Do not use a quick-pickle formula as a substitute for a tested heat-processing recipe.`},{title:`Related theories`,text:`056, 060, 155, 218.`}]};var o={short:`Швидке маринування надає овочам кислого смаку та змінює їхню текстуру за короткий час. Такі продукти зазвичай зберігають у холодильнику: вони не стають автоматично безпечними для зберігання без охолодження.`,sections:[{title:`Суть`,text:`Огірки, цибулю або редиску заливають сумішшю оцту, води, солі й іноді цукру. Кислота та дифузія поступово змінюють смак; тонкі скибки реагують швидше за товсті.`},{title:`Наука`,text:`Органічні кислоти впливають на смак і деякі властивості рослинної тканини, а сіль і цукор впливають на переміщення води. Проникнення кислоти не миттєве, і приємний кислий смак не підтверджує безпечний pH для консервування.`},{title:`Як застосувати`,text:`Беріть чисті овочі, харчову ємність і перевірений рецепт холодильного маринування. Зберігайте в холодильнику, ставте дату та дотримуйтеся вказаного терміну. Для консервації без холодильника потрібна інша перевірена технологія.`},{title:`Практичний дослід`,text:`Порівняйте тонкі й товсті скибки червоної цибулі через 15 та 60 хвилин у тому самому маринаді. Оцініть колір, хрумкість і різкість смаку.`},{title:`Поширені помилки`,text:`Довільне зменшення оцту й припущення, що будь-яка кислота усуває ризик ботулізму, небезпечні. Рецепт швидкого маринування не можна прирівнювати до перевіреного рецепта домашньої консервації.`},{title:`Пов’язані теорії`,text:`056, 060, 155, 218.`}]};var c=[56,60,155,218];var d=`References / Джерела`;var l=[`https://nchfp.uga.edu/how/pickle`,`https://www.fda.gov/food/buy-store-serve-safe-food/safe-food-handling`];var u={id:158,slug:i,group:`154`,title:r,en:n,ua:o,related:c,referenceTitle:d,references:l};export{u as default,n as en,s as group,a as id,d as referenceTitle,l as references,c as related,i as slug,r as title,o as ua};